class Fox:
    def __init__(self, n):
        self.n = n
a = Fox(1)
b = Fox(1)
assert a != b
assert a == a
class Fox2(Fox):
    def __eq__(self, o):
        return self.n == o.n
assert Fox2(1) == Fox2(1)

class Fox:
    pass
class Dog:
    pass
assert isinstance(Fox(), Fox)
assert not isinstance(Dog(), Fox)

class A:
    def a(self):
        return 1
    def b(self):
        return self.a() + 1
assert A().b() == 2

class A:
    def m(self):
        return 5
assert A().m() == 5
assert A().m != 5
assert callable(A().m)

class A:
    def m(self):
        return False
assert bool(A().m) is True
assert bool(A().m()) is False

class A:
    def other(self):
        return 'o'
    def m(self):
        return self.other()
assert A().m() == 'o'

from dataclasses import dataclass
@dataclass
class P:
    name: str
p = P(123)
assert p.name == 123
